sealed class CounterState {
  const CounterState();
}

class CounterLoading extends CounterState {
  const CounterLoading();
}

class CounterError extends CounterState {
  const CounterError(this.message);
  final String message;
}

class CounterReady extends CounterState {
  const CounterReady(this.value, {this.saving = false});
  final int value;
  final bool saving;
}

// En la UI, el switch es exhaustivo: si añades una variante,
// el compilador te obliga a tratarla aquí.
Widget build(BuildContext context) => switch (state) {
  CounterLoading() => const CircularProgressIndicator(),
  CounterError(:final message) => ErrorView(message, onRetry: load),
  CounterReady(:final value, :final saving) => CounterView(
      value: value,
      onIncrement: saving ? null : increment,
    ),
};
