class PagedState {
  const PagedState({
    this.items = const [],
    this.nextPage = 0,
    this.isLoading = false,
    this.hasMore = true,
    this.error,
  });

  final List<Item> items;
  final int nextPage;
  final bool isLoading;
  final bool hasMore;
  final String? error;
}

Future<void> loadNext() async {
  // El guard: sin esto, un scroll rápido dispara la misma página varias veces.
  if (state.isLoading || !state.hasMore) return;
  state = state.copyWith(isLoading: true, error: null);
  try {
    final page = await api.fetch(state.nextPage);
    state = state.copyWith(
      items: [...state.items, ...page],
      nextPage: state.nextPage + 1,
      hasMore: page.length == pageSize,
      isLoading: false,
    );
  } catch (error) {
    // Se conservan los items ya cargados.
    state = state.copyWith(isLoading: false, error: '$error');
  }
}

// En el builder: al acercarse al final, pide más.
itemBuilder: (context, index) {
  if (index >= state.items.length - 5) loadNext();
  ...
}
