class _FeedState extends State<Feed> {
  List<Post> posts = [];
  StreamSubscription<Post>? _subscription;
  Timer? _timer;

  @override
  void initState() {
    super.initState();
    _subscription = widget.repository.stream.listen((post) {
      setState(() => posts.add(post));
    });
    _timer = Timer.periodic(const Duration(seconds: 30), (_) => refresh());
  }

  Future<void> refresh() async {
    final fresh = await widget.repository.load();
    if (!mounted) return; // el usuario pudo salir durante el await
    setState(() => posts = fresh);
  }

  @override
  void dispose() {
    _subscription?.cancel();
    _timer?.cancel();
    super.dispose();
  }
}
