class MasterDetail extends StatelessWidget {
  const MasterDetail({required this.selectedId, required this.onSelect, super.key});

  final String? selectedId;
  final ValueChanged<String?> onSelect;

  static const _expandedBreakpoint = 840.0; // Material 3: expanded

  @override
  Widget build(BuildContext context) {
    return LayoutBuilder(
      builder: (context, constraints) {
        final isWide = constraints.maxWidth >= _expandedBreakpoint;

        if (isWide) {
          return Row(
            children: [
              SizedBox(
                width: 360,
                child: ItemList(selectedId: selectedId, onSelect: onSelect),
              ),
              const VerticalDivider(width: 1),
              Expanded(
                child: selectedId == null
                    ? const EmptyDetail()
                    : ItemDetail(id: selectedId!),
              ),
            ],
          );
        }

        // Estrecho: la selección navega en lugar de rellenar un panel.
        return ItemList(
          selectedId: null,
          onSelect: (id) {
            onSelect(id);
            Navigator.of(context).push(
              MaterialPageRoute(builder: (_) => ItemDetail(id: id!)),
            );
          },
        );
      },
    );
  }
}
