class FakeAuth implements AuthRepository {
  Completer<User>? pending;
  Object? error;

  @override
  Future<User> login(String email, String password) {
    if (error != null) return Future.error(error!);
    return (pending = Completer<User>()).future;
  }
}

testWidgets('deshabilita el botón mientras el login está en vuelo',
    (tester) async {
  final auth = FakeAuth();
  await tester.pumpWidget(wrap(LoginScreen(auth: auth)));

  await tester.enterText(find.byKey(const Key('email')), 'a@b.com');
  await tester.enterText(find.byKey(const Key('password')), 'secreto');
  await tester.tap(find.byKey(const Key('submit')));

  // Un solo frame: estamos dentro del estado de carga.
  await tester.pump();

  final button = tester.widget<FilledButton>(find.byKey(const Key('submit')));
  expect(button.onPressed, isNull);
  expect(find.byType(CircularProgressIndicator), findsOneWidget);

  // Ahora sí, resolvemos y dejamos que termine.
  auth.pending!.complete(const User(id: '1'));
  await tester.pumpAndSettle();

  expect(find.byType(CircularProgressIndicator), findsNothing);
});
