// Mal: async no evita el bloqueo. El hilo de UI sigue parado 2 s.
Future<List<Item>> parseBad(String json) async {
  final raw = jsonDecode(json) as List;      // bloquea aquí
  return raw.map(Item.fromJson).toList();
}

// Bien: el trabajo pesado va a otro isolate.
Future<List<Item>> parseGood(String json) {
  return Isolate.run(() {
    final raw = jsonDecode(json) as List;
    return raw.map((e) => Item.fromJson(e as Map<String, dynamic>)).toList();
  });
}

// Mejor: descargar Y parsear dentro del isolate, para no copiar
// los 20 MB del string a través de la frontera.
Future<List<Item>> fetchAndParse(Uri url) {
  return Isolate.run(() async {
    final response = await http.get(url);
    final raw = jsonDecode(response.body) as List;
    return raw.map((e) => Item.fromJson(e as Map<String, dynamic>)).toList();
  });
}
