enum OpStatus { pending, inFlight, failed }

class PendingOp {
  const PendingOp({
    required this.id,        // UUID del cliente = clave de idempotencia
    required this.entityId,  // para ordenar por entidad
    required this.type,
    required this.payload,
    this.attempts = 0,
    this.status = OpStatus.pending,
  });
  // ... campos
}

Future<void> processQueue() async {
  final pending = await db.pendingOps(); // ordenadas por createdAt
  for (final op in pending) {
    try {
      // El servidor usa op.id para descartar duplicados.
      await api.apply(op, idempotencyKey: op.id);
      await db.remove(op.id);
    } on PermanentFailure catch (error) {
      // 4xx de validación: reintentar no cambia nada.
      await db.markFailed(op.id, '$error');
      notifyUser(op, error);
    } on TransientFailure {
      // Red o 5xx: backoff exponencial con jitter.
      final delay = Duration(
        milliseconds: (1000 * pow(2, op.attempts)).toInt() +
            Random().nextInt(1000),
      );
      await db.scheduleRetry(op.id, after: delay);
      break; // preservar el orden: no saltar a la siguiente
    }
  }
}
