class RenderChipWrap extends RenderBox
    with
        ContainerRenderObjectMixin<RenderBox, BoxParentData>,
        RenderBoxContainerDefaultsMixin<RenderBox, BoxParentData> {
  RenderChipWrap({required double spacing, required double runSpacing})
      : _spacing = spacing,
        _runSpacing = runSpacing;

  double _spacing;
  double _runSpacing;

  @override
  void setupParentData(RenderBox child) {
    if (child.parentData is! BoxParentData) child.parentData = BoxParentData();
  }

  @override
  void performLayout() {
    final maxWidth = constraints.maxWidth;
    // Restricciones loose: cada hijo elige su tamaño natural.
    final childConstraints = BoxConstraints(maxWidth: maxWidth);

    var child = firstChild;
    final rows = <List<RenderBox>>[[]];
    var rowWidth = 0.0;

    // Fase 1: medir y repartir en filas.
    while (child != null) {
      child.layout(childConstraints, parentUsesSize: true);
      final needed = rows.last.isEmpty ? child.size.width
                                       : _spacing + child.size.width;
      if (rowWidth + needed > maxWidth && rows.last.isNotEmpty) {
        rows.add([]);
        rowWidth = child.size.width;
      } else {
        rowWidth += needed;
      }
      rows.last.add(child);
      child = (child.parentData! as BoxParentData).nextSibling;
    }

    // Fase 2: colocar, alineando cada fila por su línea base.
    var y = 0.0;
    for (final row in rows) {
      final baseline = row
          .map((c) => c.getDistanceToBaseline(TextBaseline.alphabetic) ??
              c.size.height)
          .reduce(max);
      final rowHeight = row
          .map((c) => baseline -
              (c.getDistanceToBaseline(TextBaseline.alphabetic) ??
                  c.size.height) +
              c.size.height)
          .reduce(max);

      var x = 0.0;
      for (final c in row) {
        final childBaseline =
            c.getDistanceToBaseline(TextBaseline.alphabetic) ?? c.size.height;
        (c.parentData! as BoxParentData).offset =
            Offset(x, y + baseline - childBaseline);
        x += c.size.width + _spacing;
      }
      y += rowHeight + _runSpacing;
    }

    size = constraints.constrain(
      Size(maxWidth, (y - _runSpacing).clamp(0.0, double.infinity)),
    );
  }

  @override
  void paint(PaintingContext context, Offset offset) =>
      defaultPaint(context, offset);

  @override
  bool hitTestChildren(BoxHitTestResult result, {required Offset position}) =>
      defaultHitTestChildren(result, position: position);
}
